/* 명시적 검토·저장 버튼에서만 실행하는 MON-01 Description 작성 초안. 자동 복원하지 않는다. */
(()=>{'use strict';
if(new URL(location.href).searchParams.get('descriptionDraft')!=='mon01')return;
const drafts=[{"spec":{"format":"description-spec-v1","item":"연결 상태·[실시간 업데이트] 아이콘","type":"기타","defaultValue":"연결됨","required":"N","detail":"- 연결됨·연결 끊어짐·재연결 중 상태 표시\n- 아이콘 클릭 시 재연결 후 최신 데이터 갱신","policy":"- 연결이 끊기면 자동 갱신을 중단하고, 복구 시 재개한다.\n- 연결 실패 시 기존 데이터를 유지하며 실패를 0건으로 표시하지 않는다.","planningNote":""},"anchor":{"selector":"#content .dashboard-live-control","sample":"","x":0,"y":0,"offsetX":-10,"offsetY":0}},{"spec":{"format":"description-spec-v1","item":"전체·구매·수출 탭","type":"라디오박스","defaultValue":"전체","required":"N","detail":"- 선택한 탭에 따라 상단 집계와 구매·수출 대시보드 표시","policy":"- 선택한 행사에 해당하는 데이터만 조회한다.\n- 전체는 구매·수출을 함께 표시하고, 구매·수출 탭은 해당 유형만 표시한다.","planningNote":""},"anchor":{"selector":"#content .toolbar:has([data-action=\"kind\"])","sample":"","x":0,"y":0,"offsetX":-10,"offsetY":0}},{"spec":{"format":"description-spec-v1","item":"진행 상담 건수","type":"기타","defaultValue":"해당 없음","required":"N","detail":"- QR 스캔으로 상담을 시작하고 아직 종료하지 않은 상담 수 집계","policy":"- 사람 수가 아닌 진행 중인 상담 건수로 집계한다.","planningNote":"- 상담 종료를 임시 저장·승인 요청 시 자동 처리할지, 별도 종료 버튼으로 처리할지 협의 필요.\n- 일별 초기화 대상과 실행 시점 협의 필요. \n- 상담 중 동일 QR 재스캔 시 기존 상담 유지·중복 생성 방지 방식 협의 필요."},"anchor":{"selector":"#content .monitoring-count-kpis .kpi:nth-child(1)","sample":"","x":0,"y":0,"offsetX":-10,"offsetY":0}},{"spec":{"format":"description-spec-v1","item":"상담일지 등록 건수","type":"기타","defaultValue":"해당 없음","required":"N","detail":"- 승인 요청·반려·승인 완료 상태의 상담일지 수 집계","policy":"- 작성 중 일지는 제외한다.\n- 같은 일지는 반려·승인 재요청 횟수와 관계없이 1건으로 집계한다.","planningNote":"- 당일·행사 누적 집계 범위와 상담일·제출일·승인일 중 날짜 기준 협의 필요.\n- 일별 초기화 적용 여부와 실행 시점 협의 필요."},"anchor":{"selector":"#content .monitoring-count-kpis .kpi:nth-child(2)","sample":"","x":0,"y":0,"offsetX":-10,"offsetY":0}},{"spec":{"format":"description-spec-v1","item":"계약 추진 건수","type":"기타","defaultValue":"해당 없음","required":"N","detail":"- 승인 완료 일지 중 계약 추진액이 0보다 큰 일지 수 집계","policy":"- 공란·0·금액 산정 불가 일지는 제외한다.\n- 실제 계약 체결 건수가 아닌 상담일지 수로 집계한다.","planningNote":"- 당일·행사 누적 집계 범위, 날짜 기준 및 일별 초기화 적용 여부 협의 필요."},"anchor":{"selector":"#content .monitoring-count-kpis .kpi:nth-child(3)","sample":"","x":0,"y":0,"offsetX":-10,"offsetY":0}},{"spec":{"format":"description-spec-v1","item":"구매 상담 금액·계약 추진 금액","type":"기타","defaultValue":"해당 없음","required":"N","detail":"- 승인 완료된 구매상담일지의 상담액·계약 추진액을 각각 합산","policy":"- KRW 기준으로 합산하며 구매·수출 금액을 합산하거나 환산하지 않는다.\n- 공란·0·금액 산정 불가는 구분하며, 숫자로 입력된 금액만 합산한다.\n- 승인 완료 처리 시 집계에 반영한다.","planningNote":"- 당일·행사 누적 집계 범위, 날짜 기준 및 일별 초기화 적용 여부 협의 필요."},"anchor":{"selector":"#content .overview-module[aria-label=\"구매상담 대시보드\"] .monitoring-module-money","sample":"","x":0,"y":0,"offsetX":-10,"offsetY":0}},{"spec":{"format":"description-spec-v1","item":"수출 상담 금액·계약 추진 금액","type":"기타","defaultValue":"해당 없음","required":"N","detail":"- 승인 완료된 수출상담일지의 상담액·계약 추진액을 각각 합산","policy":"- USD 기준으로 합산하며 구매·수출 금액을 합산하거나 환산하지 않는다.\n- 공란·0·금액 산정 불가는 구분하며, 숫자로 입력된 금액만 합산한다.\n- 승인 완료 처리 시 집계에 반영한다.","planningNote":"- 당일·행사 누적 집계 범위, 날짜 기준 및 일별 초기화 적용 여부 협의 필요."},"anchor":{"selector":"#content .overview-module[aria-label=\"수출상담 대시보드\"] .monitoring-module-money","sample":"","x":0,"y":0,"offsetX":-10,"offsetY":0}},{"spec":{"format":"description-spec-v1","item":"비즈니스 유형별 국내 바이어 수","type":"기타","defaultValue":"해당 없음","required":"N","detail":"- 현재 행사 참가 국내 바이어 전체 인원과 비즈니스 유형별 인원·비율 표시","policy":"- 유형별 인원 ÷ 전체 참가 국내 바이어 수 × 100으로 비율을 계산한다.\n- 복수 선택한 바이어는 각 유형에 1명씩 포함하며, 동일 유형에는 중복 집계하지 않는다.\n- 유형 미등록자는 전체 인원에 포함하고 유형별 인원에서는 제외한다.\n- 전체 인원이 0명이면 비율은 0%로 표시한다.\n- 복수 선택으로 유형별 비율 합계는 100%를 초과할 수 있다.","planningNote":"","dataSource":"[기본정보관리 > 국내 바이어] 비즈니스 유형 / [행사정보 > 국내 바이어] 현재 행사 참가자"},"anchor":{"selector":"#content .overview-chart:has(.dashboard-business-types)","sample":"","x":0,"y":0,"offsetX":-10,"offsetY":0}},{"spec":{"format":"description-spec-v1","item":"해외 바이어 방한 정보","type":"기타","defaultValue":"해당 없음","required":"N","detail":"- 현재 행사 참가 해외 바이어를 현재 상태별로 집계\n- [더보기 +] 클릭 시 해외 바이어 목록(PRE-01)으로 이동","policy":"- 바이어별 가장 최근 상태에 1명씩 집계하며 과거 상태에 중복 집계하지 않는다.\n- 미입국 상태를 포함하고, 방한 상태 변경 시 집계에 반영한다.","planningNote":"- 일별 상태 초기화 대상과 실행 시점 협의 필요.","dataSource":"[행사정보 > 해외 바이어](PRE-01)의 현재 방한 상태"},"anchor":{"selector":"#content .overview-chart:has(.overview-travel)","sample":"","x":0,"y":0,"offsetX":-10,"offsetY":0}},{"spec":{"format":"description-spec-v1","item":"구매상담일지 상태별 현황","type":"기타","defaultValue":"해당 없음","required":"N","detail":"- 구매상담일지를 현재 처리 상태별로 집계\n- 전체 일지는 작성 중·승인 요청·승인 완료·반려 건수의 합계 표시","policy":"- 일지별 현재 상태에 1건씩 집계하고 처리 이력 횟수는 합산하지 않는다.\n- 상태 변경 시 기존 상태에서 제외하고 변경 상태에 반영한다.","planningNote":"- 당일·행사 누적 집계 범위, 날짜 기준 및 일별 초기화 적용 여부 협의 필요."},"anchor":{"selector":"#content .overview-module[aria-label=\"구매상담 대시보드\"] .overview-chart:has(.overview-status)","sample":"","x":0,"y":0,"offsetX":-10,"offsetY":0}},{"spec":{"format":"description-spec-v1","item":"수출상담일지 상태별 현황","type":"기타","defaultValue":"해당 없음","required":"N","detail":"- 수출상담일지를 현재 처리 상태별로 집계\n- 전체 일지는 작성 중·승인 요청·승인 완료·반려 건수의 합계 표시","policy":"- 일지별 현재 상태에 1건씩 집계하고 처리 이력 횟수는 합산하지 않는다.\n- 상태 변경 시 기존 상태에서 제외하고 변경 상태에 반영한다.","planningNote":"- 당일·행사 누적 집계 범위, 날짜 기준 및 일별 초기화 적용 여부 협의 필요."},"anchor":{"selector":"#content .overview-module[aria-label=\"수출상담 대시보드\"] .overview-chart:has(.overview-status)","sample":"","x":0,"y":0,"offsetX":-10,"offsetY":0}},{"spec":{"format":"description-spec-v1","item":"구매 품목별 상담 현황","type":"기타","defaultValue":"해당 없음","required":"N","detail":"- 승인 완료된 구매상담일지의 상담 제품 메인 카테고리별 건수 집계","policy":"- 한 일지에 여러 카테고리가 있으면 각 카테고리에 1건씩 집계한다.\n- 같은 일지의 동일 카테고리는 제품 행 수와 관계없이 1건으로 집계한다.\n- 카테고리가 없는 일지는 제외한다.\n- 품목별 건수 합계는 승인 완료 일지 수보다 클 수 있다.","planningNote":"- 당일·행사 누적 집계 범위, 날짜 기준 및 일별 초기화 적용 여부 협의 필요."},"anchor":{"selector":"#content .overview-module[aria-label=\"구매상담 대시보드\"] .overview-two:last-child .overview-chart:last-child","sample":"","x":0,"y":0,"offsetX":-10,"offsetY":0}},{"spec":{"format":"description-spec-v1","item":"수출 품목별 상담 현황","type":"기타","defaultValue":"해당 없음","required":"N","detail":"- 승인 완료된 수출상담일지의 상담 제품 메인 카테고리별 건수 집계","policy":"- 한 일지에 여러 카테고리가 있으면 각 카테고리에 1건씩 집계한다.\n- 같은 일지의 동일 카테고리는 제품 행 수와 관계없이 1건으로 집계한다.\n- 카테고리가 없는 일지는 제외한다.\n- 품목별 건수 합계는 승인 완료 일지 수보다 클 수 있다.","planningNote":"- 당일·행사 누적 집계 범위, 날짜 기준 및 일별 초기화 적용 여부 협의 필요."},"anchor":{"selector":"#content .overview-module[aria-label=\"수출상담 대시보드\"] .overview-two:last-child .overview-chart:last-child","sample":"","x":0,"y":0,"offsetX":-10,"offsetY":0}},{"spec":{"format":"description-spec-v1","item":"승인 요청 구매상담일지","type":"기타","defaultValue":"해당 없음","required":"N","detail":"- 현재 승인 요청 상태인 구매상담일지를 최신 제출순으로 최대 5건 표시\n- 바이어명 클릭 시 해당 일지 상세(JNL-15)로 이동\n- [더보기 +] 클릭 시 구매상담일지 목록(JNL-13)의 처리 상태를 승인 요청으로 설정하여 조회","policy":"- 재요청 일지는 가장 최근 제출 일시를 기준으로 정렬한다.\n- 승인·반려 처리된 일지는 승인 요청 목록에서 제외한다.\n- 더보기로 이동할 때 다른 검색 조건은 초기화하고 최신 제출순을 적용한다.\n- 조회 결과가 없으면 승인 요청 상담일지가 없습니다. 문구를 표시한다.","planningNote":""},"anchor":{"selector":"#dashboard-pending-buy","sample":"","x":0,"y":0,"offsetX":-10,"offsetY":0}},{"spec":{"format":"description-spec-v1","item":"승인 요청 수출상담일지","type":"기타","defaultValue":"해당 없음","required":"N","detail":"- 현재 승인 요청 상태인 수출상담일지를 최신 제출순으로 최대 5건 표시\n- 바이어명 클릭 시 해당 일지 상세(JNL-16)로 이동\n- [더보기 +] 클릭 시 수출상담일지 목록(JNL-14)의 처리 상태를 승인 요청으로 설정하여 조회","policy":"- 재요청 일지는 가장 최근 제출 일시를 기준으로 정렬한다.\n- 승인·반려 처리된 일지는 승인 요청 목록에서 제외한다.\n- 더보기로 이동할 때 다른 검색 조건은 초기화하고 최신 제출순을 적용한다.\n- 조회 결과가 없으면 승인 요청 상담일지가 없습니다. 문구를 표시한다.","planningNote":""},"anchor":{"selector":"#dashboard-pending-export","sample":"","x":0,"y":0,"offsetX":-10,"offsetY":0}}];
const overview='현재 행사 구매·수출 상담 현황과 승인 대기 상담일지를 조회합니다.';
const parse=r=>{try{return JSON.parse(r.text)}catch{return {}}};
function mark(spec){return {...spec,codexHighlights:Object.fromEntries(Object.entries(spec).filter(([k,v])=>k!=='format'&&typeof v==='string'&&v).map(([k,v])=>[k,[{start:0,end:v.length,text:v}]]))};}
let launch;
function setup(){if(location.hash!=='#MON-01'||!window.GFAIR_COLLAB?.user?.editor||launch)return;
launch=document.createElement('button');launch.className='btn';launch.textContent='MON-01 설명 초안 검토';launch.style.cssText='position:fixed;right:24px;bottom:20px;z-index:100000;background:#fff;border:2px solid #333;color:#111;padding:10px 16px';
document.body.append(launch);
launch.onclick=()=>{
const d=document.createElement('dialog');d.style.cssText='width:min(900px,90vw);max-height:85vh;overflow:auto;padding:24px;background:#fff;color:#111';
const title=document.createElement('h2');title.textContent='MON-01 디스크립션 초안 · 15개 항목';d.append(title);
const note=document.createElement('p');note.textContent='기존 설명 ID·댓글을 보존하며 저장합니다. 새 문장은 빨간색으로 표시합니다. 저장은 아래 버튼을 눌렀을 때만 실행합니다.';d.append(note);
for(const [i,entry]of drafts.entries()){const h=document.createElement('h3');h.textContent=String(i+1).padStart(2,'0')+' '+entry.spec.item;d.append(h);const pre=document.createElement('pre');pre.style.cssText='white-space:pre-wrap;font:13px/1.6 sans-serif';pre.textContent='기능상세\n'+entry.spec.detail+'\n기본정책\n'+entry.spec.policy+(entry.spec.planningNote?'\n기획비고\n'+entry.spec.planningNote:'');d.append(pre);}
const save=document.createElement('button');save.className='btn primary';save.textContent='검토한 디스크립션 서버 저장';d.append(save);
const close=document.createElement('button');close.className='btn';close.textContent='닫기';close.onclick=()=>{d.close();d.remove()};d.append(close);
const status=document.createElement('p');status.setAttribute('role','status');d.append(status);
save.onclick=async()=>{
save.disabled=true;close.disabled=true;
try{
const store=window.GFAIR_COLLAB;await store.refresh(true);
if(location.hash!=='#MON-01'||!store.user?.editor)throw Error('현재 화면과 공동작업 권한을 확인해 주세요.');
for(const [i,entry]of drafts.entries()){
status.textContent=(i+1)+'/15 저장 중: '+entry.spec.item;
const record=store.records.find(r=>r.id==='dashboard-live-control-20261028-MON-01'&&i===0||parse(r).item===entry.spec.item);
const text=JSON.stringify(mark(entry.spec));
if(record)await store.mutate('update',{id:record.id,revision:record.revision,text});
else await store.mutate('create',{screen:'MON-01',text,anchor:entry.anchor});
}
const old=store.records.find(r=>parse(r).format==='screen-overview-v1');
const text=JSON.stringify(mark({format:'screen-overview-v1',overview}));
await store.mutate(old?'update':'create',old?{id:old.id,revision:old.revision,text}:{screen:'MON-01',text,anchor:{selector:'#content',sample:'화면 개요',x:0,y:0}});
status.textContent='15개 설명과 화면 개요 서버 저장 완료';launch.textContent='MON-01 설명 서버 저장 완료';launch.disabled=true;window.dispatchEvent(new Event('annotation-render'));
}catch(e){status.textContent=e.message;save.disabled=false;}finally{close.disabled=false;}
};
document.body.append(d);d.showModal();
};}
window.addEventListener('collaboration-updated',setup);setup();
})();